/**
 * Keys for field-level encryption of clinical text (B3.2, ADR 0002).
 *
 * Providers (FIELD_ENCRYPTION_PROVIDER):
 *   env      FIELD_ENCRYPTION_KEYS="k1:<64 hex>,k2:<64 hex>"  (dev / CI / interim)
 *   aws-kms  FIELD_ENCRYPTION_KMS_WRAPPED_KEYS="k1:<base64 CiphertextBlob>,…"
 *            Data keys generated by AWS KMS (GenerateDataKey, AES_256, with
 *            encryption context purpose=medoflow-field-encryption,kid=<kid>)
 *            and unwrapped once at boot. Plaintext keys live only in memory.
 *
 * FIELD_ENCRYPTION_ACTIVE_KID names the key new values are sealed with; the
 * others stay readable so rotation is: add key → switch active → run
 * `ops:encrypt-phi` (re-seals every value) → remove the old key.
 */
export interface Keyring {
  activeKid: string
  keys: Map<string, Buffer>
}

export type FieldKeyProvider = 'env' | 'aws-kms'

export const KMS_ENCRYPTION_CONTEXT_PURPOSE = 'medoflow-field-encryption'

const KID_RE = /^[a-zA-Z0-9_-]{1,32}$/

export function getFieldKeyProvider(env: NodeJS.ProcessEnv = process.env): FieldKeyProvider {
  const p = (env.FIELD_ENCRYPTION_PROVIDER || 'env').trim()
  if (p !== 'env' && p !== 'aws-kms') {
    throw new Error(`FIELD_ENCRYPTION_PROVIDER must be "env" or "aws-kms" (got "${p}")`)
  }
  return p
}

/** "k1:abc,k2:def" → [["k1","abc"],["k2","def"]] */
export function parseKeyList(raw: string | undefined): [string, string][] {
  if (!raw?.trim()) return []
  return raw.split(',').map((entry) => {
    const i = entry.indexOf(':')
    const kid = entry.slice(0, i).trim()
    const value = entry.slice(i + 1).trim()
    if (i <= 0 || !KID_RE.test(kid) || !value) {
      throw new Error('Field encryption key list must look like "k1:<key>,k2:<key>"')
    }
    return [kid, value]
  })
}

function buildKeyring(entries: [string, Buffer][], activeKid: string | undefined): Keyring {
  const keys = new Map<string, Buffer>()
  for (const [kid, key] of entries) {
    if (key.length !== 32) throw new Error(`Field encryption key "${kid}" must be 32 bytes`)
    if (keys.has(kid)) throw new Error(`Field encryption key "${kid}" is listed twice`)
    keys.set(kid, key)
  }
  const active = activeKid?.trim() || (entries.length === 1 ? entries[0]![0] : '')
  if (!active)
    throw new Error('FIELD_ENCRYPTION_ACTIVE_KID is required when several keys are listed')
  if (!keys.has(active))
    throw new Error(`FIELD_ENCRYPTION_ACTIVE_KID "${active}" is not in the key list`)
  return { activeKid: active, keys }
}

/** env provider: keys straight from FIELD_ENCRYPTION_KEYS. Null when unset. */
export function loadEnvKeyring(env: NodeJS.ProcessEnv = process.env): Keyring | null {
  const entries = parseKeyList(env.FIELD_ENCRYPTION_KEYS)
  if (entries.length === 0) return null
  return buildKeyring(
    entries.map(([kid, hex]) => {
      if (!/^[0-9a-fA-F]{64}$/.test(hex)) {
        throw new Error(`Field encryption key "${kid}" must be 64 hex characters`)
      }
      return [kid, Buffer.from(hex, 'hex')]
    }),
    env.FIELD_ENCRYPTION_ACTIVE_KID
  )
}

/** Unwraps one KMS-encrypted data key. Injected in tests. */
export type KmsDecrypt = (ciphertext: Buffer, context: Record<string, string>) => Promise<Buffer>

const awsKmsDecrypt =
  (env: NodeJS.ProcessEnv): KmsDecrypt =>
  async (ciphertext, context) => {
    const { KMSClient, DecryptCommand } = await import('@aws-sdk/client-kms')
    const client = new KMSClient({ region: env.FIELD_ENCRYPTION_KMS_REGION || env.AWS_REGION })
    const res = await client.send(
      new DecryptCommand({
        CiphertextBlob: ciphertext,
        EncryptionContext: context,
        ...(env.FIELD_ENCRYPTION_KMS_KEY_ID ? { KeyId: env.FIELD_ENCRYPTION_KMS_KEY_ID } : {}),
      })
    )
    if (!res.Plaintext) throw new Error('KMS returned no plaintext for a field encryption key')
    return Buffer.from(res.Plaintext)
  }

/** aws-kms provider: unwraps every listed data key through KMS. */
export async function loadKmsKeyring(
  env: NodeJS.ProcessEnv = process.env,
  decrypt: KmsDecrypt = awsKmsDecrypt(env)
): Promise<Keyring | null> {
  const entries = parseKeyList(env.FIELD_ENCRYPTION_KMS_WRAPPED_KEYS)
  if (entries.length === 0) return null
  const unwrapped: [string, Buffer][] = []
  for (const [kid, b64] of entries) {
    const key = await decrypt(Buffer.from(b64, 'base64'), {
      purpose: KMS_ENCRYPTION_CONTEXT_PURPOSE,
      kid,
    })
    unwrapped.push([kid, key])
  }
  return buildKeyring(unwrapped, env.FIELD_ENCRYPTION_ACTIVE_KID)
}

let keyring: Keyring | null | undefined

/**
 * The loaded keyring. The env provider loads lazily on first use; aws-kms
 * needs initFieldEncryption() at boot and stays null (fail closed) until then.
 */
export function getKeyring(): Keyring | null {
  if (keyring === undefined && getFieldKeyProvider() === 'env') keyring = loadEnvKeyring()
  return keyring ?? null
}

/** Boot: load (and for aws-kms, unwrap) the keys. Throws on misconfiguration. */
export async function initFieldEncryption(
  env: NodeJS.ProcessEnv = process.env,
  decrypt?: KmsDecrypt
): Promise<Keyring | null> {
  keyring =
    getFieldKeyProvider(env) === 'aws-kms'
      ? await loadKmsKeyring(env, decrypt)
      : loadEnvKeyring(env)
  return keyring
}

/** Test seam: forget the loaded keyring so the next use reloads from env. */
export function resetFieldKeysForTests(): void {
  keyring = undefined
}

/**
 * Boot-time configuration problem for envValidation (null when fine).
 * Static checks only — the KMS unwrap itself happens in initFieldEncryption.
 */
export function fieldEncryptionConfigProblem(env: NodeJS.ProcessEnv = process.env): string | null {
  try {
    const provider = getFieldKeyProvider(env)
    if (provider === 'aws-kms') {
      const entries = parseKeyList(env.FIELD_ENCRYPTION_KMS_WRAPPED_KEYS)
      if (entries.length === 0) return 'FIELD_ENCRYPTION_KMS_WRAPPED_KEYS is not set'
      if (entries.length > 1 && !env.FIELD_ENCRYPTION_ACTIVE_KID) {
        return 'FIELD_ENCRYPTION_ACTIVE_KID is required when several keys are listed'
      }
      return null
    }
    return loadEnvKeyring(env)
      ? null
      : 'FIELD_ENCRYPTION_KEYS is not set — transcripts, SOAP notes and intake answers would be stored unencrypted'
  } catch (e) {
    return (e as Error).message
  }
}
